{
    "faq": {
        "title": "Preguntas Frecuentes",
        "description": "Preguntas comunes sobre cómo funciona BitTasker para taskers y taskees.",
        "general": {
            "title": "Preguntas Generales",
            "0": {
                "question": "¿Qué es BitTasker?",
                "answer": "BitTasker es una plataforma comunitaria confiable que conecta a personas que necesitan externalizar tareas y encontrar servicios locales con personas que buscan ganar dinero y están listas para trabajar. Desde tareas simples hasta complejas, BitTasker puede ayudarte a completar limpieza del hogar, trabajos de mantenimiento, asistencia administrativa, fotografía, diseño gráfico o incluso construir un sitio web."
            },
            "1": {
                "question": "¿Cómo funciona BitTasker?",
                "step_1_title": "Publica tu tarea:",
                "step_1_text": "Describe lo que necesitas hacer y establece un presupuesto justo. ¡Publicar es gratis!",
                "step_2_title": "Revisa ofertas:",
                "step_2_text": "Recibe ofertas de Taskees calificados. Compara sus perfiles, calificaciones y reseñas.",
                "step_3_title": "Contrata y financia:",
                "step_3_text": "Elige al mejor Taskee y financia la tarea con Bitcoin o dinero fiat. El pago se mantiene seguro en nuestro escrow hasta que se complete la tarea.",
                "step_4_title": "Tarea completada:",
                "step_4_text": "Una vez que estés satisfecho, libera el pago al Taskee. ¡Deja una reseña para ayudar a la comunidad!"
            }
        },
        "taskers": {
            "title": "Para Taskers",
            "0": {
                "question": "¿Cómo publico una tarea?",
                "answer": "Simplemente crea una cuenta, haz clic en \"Publicar una tarea\" y completa los detalles. Proporciona una descripción clara, establece un presupuesto justo y especifica tu cronograma. Cuantos más detalles proporciones, mejores ofertas recibirás de los taskees."
            },
            "1": {
                "question": "¿Cómo funciona el pago?",
                "answer": "Cuando aceptas una oferta, tu pago se asegura de inmediato en nuestro sistema de escrow con Bitcoin. Una vez que el taskee completa el trabajo a tu satisfacción, liberas el pago. Si no tomas acción en un plazo de 7 días, el pago se libera automáticamente al taskee."
            },
            "2": {
                "question": "¿Qué pasa si no estoy satisfecho con el trabajo?",
                "answer": "Si no estás satisfecho con el trabajo, puedes iniciar una disputa. El pago permanecerá bloqueado mientras ambas partes buscan una solución justa. Nuestro proceso de resolución de disputas está diseñado para ser justo y transparente."
            },
            "3": {
                "question": "¿Puedo cancelar una tarea?",
                "answer": "Sí, puedes cancelar una tarea en cualquier momento. Si la cancelas antes de que comience el trabajo, recibirás un reembolso completo. Si el trabajo ya ha comenzado, es posible que debas pagar una parte según el progreso realizado."
            },
            "4": {
                "question": "¿Cuáles son las tarifas para los taskers?",
                "answer": "BitTasker utiliza un sistema de niveles dinámico que recompensa a los taskers activos con tarifas más bajas. Cuantas más tareas completes, menos pagas. Consulta nuestra página de <a href=\"/tasker-fees\" class=\"text-primary hover:underline\">Tarifas para Taskers</a> para más detalles."
            }
        },
        "taskees": {
            "title": "Para Taskees",
            "0": {
                "question": "¿Cómo encuentro tareas?",
                "answer": "Explora las tareas disponibles en tu área y según tus habilidades. Puedes filtrar por categoría, ubicación, presupuesto y plazo. Cuando encuentres una tarea que se adapte a tus habilidades, envía una oferta competitiva con tu enfoque y cronograma propuesto."
            },
            "1": {
                "question": "¿Cómo me pagan?",
                "answer": "Cuando un tasker acepta tu oferta, el pago se asegura inmediatamente en un escrow. Una vez completes el trabajo y el tasker lo apruebe, el pago se libera a ti. Si el tasker no responde en 7 días, se te paga automáticamente."
            },
            "2": {
                "question": "¿Qué pasa si el tasker no aprueba mi trabajo?",
                "answer": "Si un tasker disputa tu trabajo, pueden discutir el problema y buscar una solución. Nuestro proceso de resolución de disputas es justo y transparente. Si no se llega a un acuerdo, el sistema sigue un proceso claro para garantizar un resultado justo."
            },
            "3": {
                "question": "¿Cuáles son las tarifas para los taskees?",
                "answer": "BitTasker utiliza un sistema de niveles dinámico que recompensa a los taskees activos con tarifas más bajas. Cuantas más tareas completes, menos pagarás. Consulta nuestra página de <a href=\"/taskee-fees\" class=\"text-primary hover:underline\">Tarifas de Taskees</a> para obtener todos los detalles."
            },
            "4": {
                "question": "¿Necesito tener Bitcoin?",
                "answer": "No, no necesitas tener Bitcoin para usar BitTasker. También puedes usar moneda fiat. Puedes recibir pagos en Bitcoin o USDT y convertirlos a tu moneda local si lo deseas."
            }
        },
        "payment": {
            "title": "Pagos y Bitcoin",
            "0": {
                "question": "¿Por qué usar Bitcoin?",
                "answer": "Bitcoin es libertad: una moneda imparable y transfronteriza que te permite enviar pagos a cualquier persona, en cualquier lugar y en cualquier momento. Usamos la red Liquid para transacciones de bajo costo y casi instantáneas."
            },
            "1": {
                "question": "¿Cuáles son las tarifas?",
                "answer_1": "BitTasker cobra una tarifa de servicio cuando se completa una tarea con éxito. Esta tarifa nos ayuda a operar la plataforma, brindar soporte y desarrollar nuevas funciones. La tarifa es un porcentaje del precio de la tarea y se muestra cuando haces una oferta.",
                "answer_2": "Además, existen tarifas de transacción de red al enviar Bitcoin o USDT. Estas tarifas las cobra la red blockchain (Liquid, Bitcoin o Lightning, según cómo se realice el pago) y no están bajo nuestro control ni las recibimos. En las redes Liquid y Lightning, estas tarifas suelen ser muy pequeñas, típicamente de $0.01 o menos."
            },
            "3": {
                "question": "Can I cancel a task?",
                "answer": "Sí, puedes cancelar una tarea en cualquier momento. Si la cancelas antes de que comience el trabajo, recibirás un reembolso completo. Si el trabajo ya ha comenzado, es posible que debas pagar una parte según el progreso realizado."
            }
        },
        "safety": {
            "title": "Confianza y Seguridad",
            "0": {
                "question": "¿Es seguro mi pago?",
                "answer": "Sí. Cuando un Tasker financia una tarea, los fondos se mantienen en una billetera de custodia con multifirma 2-de-2. Esto significa que ni el Tasker ni el Taskee pueden mover los fondos por su cuenta. El pago solo se libera cuando la tarea se marca como completada y es aprobada, o cuando ambas partes acuerdan un resultado distinto."
            },
            "1": {
                "question": "¿Qué pasa si algo sale mal?",
                "answer": "Nuestro sistema de custodia automatizado tiene reglas integradas para cancelaciones, cambios y disputas, lo que garantiza un resultado justo. Si no puedes resolver el problema directamente con la otra parte, el sistema de custodia garantiza el resultado más justo."
            }
        }
    }
}
